import { connect } from 'node:net';
import { startServer } from '/opt/gsb-production/workspaces/coco/prod-19/A/task023/testing/server.ts';

const server = await startServer('/tmp/fh-probe/data');
const url = new URL(server.origin);

function rawRequest(head: string, pieces: Buffer[], chunked: boolean, delayMs: number): Promise<{status:number; body:string}> {
  return new Promise((resolve, reject) => {
    const sock = connect(Number(url.port), url.hostname);
    sock.setNoDelay(true);
    let acc = Buffer.alloc(0);
    let settled = false;
    sock.on('error', (e) => { if (!settled) { settled = true; reject(e); } });
    const finish = () => {
      const idx = acc.indexOf('\r\n\r\n');
      const headTxt = acc.subarray(0, idx).toString();
      const m = headTxt.match(/HTTP\/1\.1 (\d+)/);
      const body = acc.subarray(idx + 4);
      const cl = Number((headTxt.match(/content-length: (\d+)/i) ?? [])[1]);
      if (m && body.length >= cl) {
        settled = true;
        resolve({ status: Number(m[1]), body: body.toString('utf8') });
        sock.end();
      }
    };
    sock.on('data', (c) => { acc = Buffer.concat([acc, c]); finish(); });
    sock.on('end', finish);
    sock.on('connect', async () => {
      sock.write(head);
      await new Promise(r => setTimeout(r, 50));
      for (let i = 0; i < pieces.length; i++) {
        if (chunked) sock.write(Buffer.from(`${pieces[i].length.toString(16)}\r\n`, 'ascii'));
        sock.write(pieces[i]);
        if (chunked) sock.write(Buffer.from('\r\n', 'ascii'));
        await new Promise(r => setTimeout(r, delayMs));
      }
      if (chunked) sock.write(Buffer.from('0\r\n\r\n', 'ascii'));
    });
  });
}

const MAX = 1_000_000;
const fixed = '{"title":"字节边界标题","description":"字节边界说明，含中文😀。","scenario":"场景 中😀","padding":"';
const fixedTail = '"}';
const head = Buffer.from(fixed, 'utf8');
const tail = Buffer.from(fixedTail, 'utf8');
const exact = Buffer.concat([head, Buffer.from('x'.repeat(MAX - head.length - tail.length)), tail]);
console.log('exact bytes', exact.length, Buffer.byteLength(fixed));

// 1) chunked exact, cut inside multibyte: '边' byte offset?
const titleIdx = exact.indexOf(Buffer.from('边', 'utf8'));
const emojiIdx = exact.indexOf(Buffer.from('😀', 'utf8'));
console.log('边 offset', titleIdx, '😀 offset', emojiIdx);
const cuts = [titleIdx + 1, emojiIdx + 2, emojiIdx + 300000, 700000];
const pieces: Buffer[] = [];
let prev = 0;
for (const c of cuts) { pieces.push(exact.subarray(prev, c)); prev = c; }
pieces.push(exact.subarray(prev));
console.log('pieces', pieces.map(p => p.length));

const headStr = `POST /api/ideas HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Type: application/json\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n`;
const r1 = await rawRequest(headStr, pieces, true, 15);
console.log('chunked exact status', r1.status, r1.body.slice(0, 200));

// 2) chunked oversized mid-stream, invalid json prefix looks like complete idea
const prefix = Buffer.from('{"title":"前缀像完整意见","description":"前缀说明"}', 'utf8');
const rest = Buffer.concat([Buffer.from(' '.repeat(MAX - prefix.length)), Buffer.from('X')]);
console.log('oversize total', prefix.length + rest.length);
const r2 = await rawRequest(headStr, [prefix, rest.subarray(0, 200000), rest.subarray(200000)], true, 15);
console.log('chunked oversize+invalid status', r2.status, r2.body);

// 3) content-length oversized declared, client drains slowly
const bad = Buffer.concat([Buffer.from('{not json'), Buffer.from(' '.repeat(MAX - 9))]);
console.log('bad len', bad.length);
const clHead = `POST /api/ideas HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Type: application/json\r\nContent-Length: ${bad.length}\r\nConnection: close\r\n\r\n`;
const chunks: Buffer[] = [];
for (let i = 0; i < bad.length; i += 200000) chunks.push(bad.subarray(i, i + 200000));
const r3 = await rawRequest(clHead, chunks, false, 15);
console.log('CL oversize+invalid status', r3.status, r3.body);

// list check
const res = await fetch(`${server.origin}/api/ideas`).then(r => r.json());
console.log('saved count', res.ideas.length, res.ideas[0]?.title, res.ideas[0]?.description?.includes('😀'));
await server.stop();
